42	function playerCompleteness(p: Player): number {
43	  const fields = [p.archetype, p.role, p.faction, p.motivation, p.flaw, p.strategy, p.specialAbility, p.description];
44	  return Math.round((fields.filter(Boolean).length / fields.length) * 100);
45	}
