95	// ─── JSONB cast helpers ────────────────────────────────────────────────────────
96	
97	function castBehavior(raw: Record<string, unknown> | null | undefined): BehaviorProfile {
98	  const defaults: BehaviorProfile = { riskTolerance: 50, aggression: 50, decisionStyle: "Optimiser" };
99	  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return defaults;
100	  const r = raw as Record<string, unknown>;
101	  return {
102	    riskTolerance: typeof r["riskTolerance"] === "number" ? Math.max(0, Math.min(100, r["riskTolerance"])) : 50,
103	    aggression: typeof r["aggression"] === "number" ? Math.max(0, Math.min(100, r["aggression"])) : 50,
104	    decisionStyle: typeof r["decisionStyle"] === "string" ? r["decisionStyle"] : "Optimiser",
105	  };
106	}
107	
108	function castRelationships(raw: Record<string, unknown>[] | null | undefined): Relationship[] {
109	  if (!Array.isArray(raw)) return [];
110	  return raw
111	    .filter((r) => {
112	      if (!r || typeof r !== "object") return false;
113	      const x = r as Record<string, unknown>;
114	      return typeof x["targetPlayerId"] === "number" && typeof x["relationshipType"] === "string";
115	    })
116	    .map((r) => r as unknown as Relationship);
117	}
