141	
142	function emptySheet(type?: PlayerType): SheetState {
143	  return {
144	    name: "", playerType: type ?? "Character", role: "", archetype: "",
145	    faction: "", motivation: "", flaw: "", arc: "", description: "",
146	    strategy: "", startingResources: "", victoryCondition: "", specialAbility: "", playstyle: "",
147	    riskTolerance: 50, aggression: 50, decisionStyle: "Optimiser",
148	    relationships: [],
149	  };
150	}
151	
152	function playerToSheet(p: Player): SheetState {
153	  const b = castBehavior(p.behaviorProfile as Record<string, unknown> | null | undefined);
154	  return {
155	    name: p.name,
156	    playerType: (p.playerType as PlayerType) ?? "Character",
157	    role: p.role ?? "",
158	    archetype: p.archetype ?? "",
159	    faction: p.faction ?? "",
160	    motivation: p.motivation ?? "",
161	    flaw: p.flaw ?? "",
162	    arc: p.arc ?? "",
163	    description: p.description ?? "",
164	    strategy: p.strategy ?? "",
165	    startingResources: p.startingResources ?? "",
166	    victoryCondition: p.victoryCondition ?? "",
167	    specialAbility: p.specialAbility ?? "",
168	    playstyle: p.playstyle ?? "",
169	    riskTolerance: b.riskTolerance,
170	    aggression: b.aggression,
171	    decisionStyle: b.decisionStyle,
172	    relationships: castRelationships(p.relationships as Record<string, unknown>[] | null | undefined),
173	  };
174	}
175	
176	function sheetToBody(s: SheetState): Record<string, unknown> {
177	  return {
178	    name: s.name,
179	    playerType: s.playerType,
180	    role: s.role || undefined,
181	    archetype: s.archetype || undefined,
182	    faction: s.faction || undefined,
183	    motivation: s.motivation || undefined,
184	    flaw: s.flaw || undefined,
185	    arc: s.arc || undefined,
186	    description: s.description || undefined,
187	    strategy: s.strategy || undefined,
188	    startingResources: s.startingResources || undefined,
189	    victoryCondition: s.victoryCondition || undefined,
190	    specialAbility: s.specialAbility || undefined,
191	    playstyle: s.playstyle || undefined,
192	    behaviorProfile: { riskTolerance: s.riskTolerance, aggression: s.aggression, decisionStyle: s.decisionStyle },
193	    relationships: s.relationships,
194	  };
195	}
