197	// ─── Quick-add modal ───────────────────────────────────────────────────────────
198	
199	interface QuickAddModalProps {
200	  open: boolean;
201	  onClose: () => void;
202	  onCreate: (type: PlayerType, name: string, archetype?: string) => Promise<unknown>;
203	}
204	
205	function QuickAddModal({ open, onClose, onCreate }: QuickAddModalProps) {
206	  const [name, setName] = useState("");
207	  const [type, setType] = useState<PlayerType>("Character");
208	  const [archetype, setArchetype] = useState("");
209	  const [creating, setCreating] = useState(false);
210	
211	  const handleCreate = async () => {
212	    if (!name.trim()) return;
213	    setCreating(true);
214	    try {
215	      await onCreate(type, name.trim(), archetype);
216	      setName(""); setType("Character"); setArchetype("");
217	      onClose();
218	    } catch {
219	      // keep modal open and inputs intact so user can retry
220	    } finally {
221	      setCreating(false);
222	    }
223	  };
224	
225	  return (
226	    <Dialog open={open} onOpenChange={(v) => { if (!v) onClose(); }}>
227	      <DialogContent className="max-w-md">
228	        <DialogHeader>
229	          <DialogTitle className="flex items-center gap-2">
230	            <UserPlus className="h-4 w-4" /> Add Player Persona
231	          </DialogTitle>
232	        </DialogHeader>
233	
234	        {/* Type tiles */}
235	        <div>
236	          <Label className="text-xs text-muted-foreground mb-2 block">Player type</Label>
237	          <div className="grid grid-cols-3 gap-2">
238	            {PLAYER_TYPES.map((t) => {
239	              const m = getMeta(t);
240	              const active = type === t;
241	              return (
242	                <button
243	                  key={t}
244	                  onClick={() => setType(t)}
245	                  className={`flex flex-col items-center gap-1.5 py-3 px-2 rounded-xl border text-center transition-all ${
246	                    active
247	                      ? `${m.bg} border-current ${m.color}`
248	                      : "border-border text-muted-foreground hover:border-border/80 hover:bg-muted/20"
249	                  }`}
250	                >
251	                  <m.Icon className={`h-5 w-5 ${active ? m.color : ""}`} />
252	                  <span className="text-[11px] font-medium">{t}</span>
253	                </button>
254	              );
255	            })}
256	          </div>
257	        </div>
258	
259	        <div className="space-y-1">
260	          <Label className="text-xs text-muted-foreground">Name</Label>
261	          <Input
262	            autoFocus
263	            value={name}
264	            onChange={(e) => setName(e.target.value)}
265	            onKeyDown={(e) => { if (e.key === "Enter") handleCreate(); if (e.key === "Escape") onClose(); }}
266	            placeholder={`e.g. ${getMeta(type).quickRole}…`}
267	            className="h-9 text-sm"
268	          />
269	        </div>
270	
271	        <div className="space-y-1">
272	          <Label className="text-xs text-muted-foreground">Archetype (optional)</Label>
273	          <div className="flex flex-wrap gap-1.5 mb-2">
274	            {COMMON_ARCHETYPES.map((a) => (
275	              <button
276	                key={a}
277	                onClick={() => setArchetype(archetype === a ? "" : a)}
278	                className={`text-[11px] px-2.5 py-1 rounded-full border transition-colors ${
279	                  archetype === a
280	                    ? "bg-primary/15 border-primary/40 text-primary"
281	                    : "border-border text-muted-foreground hover:text-foreground"
282	                }`}
283	              >
284	                {a}
285	              </button>
286	            ))}
287	          </div>
288	          <Input
289	            value={archetype}
290	            onChange={(e) => setArchetype(e.target.value)}
291	            placeholder="Custom archetype…"
292	            className="h-8 text-sm"
293	          />
294	        </div>
295	
296	        <div className="flex gap-2 justify-end pt-1">
297	          <Button variant="ghost" size="sm" onClick={onClose}>Cancel</Button>
298	          <Button size="sm" onClick={handleCreate} disabled={!name.trim() || creating}>
299	            {creating ? <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" /> : <Plus className="h-3.5 w-3.5 mr-1.5" />}
300	            Create
301	          </Button>
302	        </div>
303	      </DialogContent>
304	    </Dialog>
305	  );
306	}
