308	// ─── Balance view ──────────────────────────────────────────────────────────────
309	
310	const RADAR_COLORS = [
311	  "#60a5fa", "#f87171", "#34d399", "#fbbf24", "#a78bfa", "#22d3ee",
312	];
313	
314	interface BalanceViewProps { players: Player[]; onReorder: (ids: number[]) => void; }
315	
316	function BalanceView({ players, onReorder }: BalanceViewProps) {
317	  const [selected, setSelected] = useState<Set<number>>(() => new Set(players.slice(0, 4).map((p) => p.id)));
318	  const [balanceTypeFilter, setBalanceTypeFilter] = useState<string | null>(null);
319	
320	  const visibleByFilter = balanceTypeFilter ? players.filter((p) => p.playerType === balanceTypeFilter) : players;
321	
322	  // Drag state for player chip reordering
323	  const [draggedId, setDraggedId] = useState<number | null>(null);
324	  const [dropTargetId, setDropTargetId] = useState<number | null>(null);
325	  const [insertBefore, setInsertBefore] = useState<boolean>(true);
326	
327	  const clearBalanceDragState = () => {
328	    setDraggedId(null);
329	    setDropTargetId(null);
330	    setInsertBefore(true);
331	  };
332	
333	  const handleBalanceDragOver = (e: React.DragEvent, id: number) => {
334	    e.preventDefault();
335	    setDropTargetId(id);
336	    const rect = e.currentTarget.getBoundingClientRect();
337	    setInsertBefore(e.clientX < rect.left + rect.width / 2);
338	  };
339	
340	  const handleBalanceDrop = (targetId: number) => {
341	    if (!draggedId || draggedId === targetId) { clearBalanceDragState(); return; }
342	    const fromIdx = players.findIndex((p) => p.id === draggedId);
343	    const toIdx = players.findIndex((p) => p.id === targetId);
344	    if (fromIdx === -1 || toIdx === -1) { clearBalanceDragState(); return; }
345	    const reordered = [...players];
346	    const [moved] = reordered.splice(fromIdx, 1);
347	    const adjustedToIdx = fromIdx < toIdx ? toIdx - 1 : toIdx;
348	    const insertAt = Math.min(insertBefore ? adjustedToIdx : adjustedToIdx + 1, reordered.length);
349	    reordered.splice(insertAt, 0, moved);
350	    clearBalanceDragState();
351	    onReorder(reordered.map((p) => p.id));
352	  };
353	
354	  // Auto-add newly created players to the selection
355	  useEffect(() => {
356	    setSelected((prev) => {
357	      const next = new Set(prev);
358	      let changed = false;
359	      players.forEach((p) => {
360	        if (!next.has(p.id)) { next.add(p.id); changed = true; }
361	      });
362	      return changed ? next : prev;
363	    });
364	  }, [players]);
365	
366	  const visiblePlayers = players.filter((p) => selected.has(p.id));
367	
368	  const radarData = useMemo(() => {
369	    const axes = ["Risk Tolerance", "Aggression", "Strategy Depth", "Completeness"];
370	    return axes.map((axis) => {
371	      const entry: Record<string, string | number> = { axis };
372	      visiblePlayers.forEach((p, i) => {
373	        const b = castBehavior(p.behaviorProfile as Record<string, unknown> | null | undefined);
374	        if (axis === "Risk Tolerance") entry[`p${i}`] = b.riskTolerance;
375	        else if (axis === "Aggression") entry[`p${i}`] = b.aggression;
376	        else if (axis === "Strategy Depth") entry[`p${i}`] = p.strategy ? Math.min(100, p.strategy.length * 1.2) : 0;
377	        else if (axis === "Completeness") {
378	          const fields = [p.archetype, p.strategy, p.startingResources, p.victoryCondition, p.specialAbility, p.playstyle, p.description, p.motivation];
379	          entry[`p${i}`] = Math.round((fields.filter(Boolean).length / fields.length) * 100);
380	        }
381	      });
382	      return entry;
383	    });
384	  }, [visiblePlayers]);
385	
386	  const comparisonFields: { label: string; key: keyof Player; icon: React.ElementType }[] = [
387	    { label: "Archetype", key: "archetype", icon: User },
388	    { label: "Role", key: "role", icon: Shield },
389	    { label: "Faction", key: "faction", icon: Users },
390	    { label: "Starting Resources", key: "startingResources", icon: Package },
391	    { label: "Victory Condition", key: "victoryCondition", icon: Trophy },
392	    { label: "Special Ability", key: "specialAbility", icon: Wand2 },
393	    { label: "Playstyle", key: "playstyle", icon: Gamepad2 },
394	  ];
395	
396	  if (players.length === 0) {
397	    return (
398	      <div className="flex flex-col items-center justify-center h-full text-center gap-3 p-8">
399	        <BarChart3 className="h-10 w-10 text-muted-foreground" />
400	        <p className="text-sm text-muted-foreground">Add players to compare them in the balance view.</p>
401	      </div>
402	    );
403	  }
404	
405	  return (
406	    <div className="p-6 space-y-6">
407	      {/* Player selector */}
408	      <div>
409	        <div className="flex items-center justify-between mb-3 border-b border-border pb-1">
410	          <h3 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Compare Players</h3>
411	          {/* Type filter chips */}
