6	interface Relationship { targetPlayerId: number; relationshipType: string; }
7	
8	function castRelationships(raw: unknown): Relationship[] {
9	  if (!Array.isArray(raw)) return [];
10	  return raw.filter((r) => {
11	    if (!r || typeof r !== "object") return false;
12	    const x = r as Record<string, unknown>;
13	    return typeof x["targetPlayerId"] === "number" && typeof x["relationshipType"] === "string";
14	  }).map((r) => r as Relationship);
15	}
