17	const REL_COLORS: Record<string, string> = {
18	  Allied: "#4ade80",
19	  Enemy: "#f87171",
20	  Rival: "#fb923c",
21	  Mentor: "#60a5fa",
22	  Dependent: "#c084fc",
23	  Neutral: "#94a3b8",
24	};
25	
26	function relColor(type: string) {
27	  return REL_COLORS[type] ?? "#94a3b8";
28	}
29	
30	function nodeColor(playerType: string) {
31	  return PLAYER_TYPE_COLORS[playerType] ?? "#7c3aed";
32	}
33	
34	function initials(name: string) {
35	  return name
36	    .split(/\s+/)
37	    .filter(Boolean)
38	    .slice(0, 2)
39	    .map((w) => w[0]!.toUpperCase())
40	    .join("") || "?";
41	}
