43	interface GraphNode extends d3.SimulationNodeDatum {
44	  id: number;
45	  name: string;
46	  playerType: string;
47	}
48	
49	// d3 resolves string|number link ids to node objects during simulation init.
50	// We use number ids here (matching GraphNode.id) so d3 can resolve them correctly.
51	interface GraphLink extends d3.SimulationLinkDatum<GraphNode> {
52	  source: number | GraphNode;
53	  target: number | GraphNode;
54	  label: string;
55	}
