63	// The graph intentionally shows the full cast topology regardless of any
64	// active search/type/faction filters in the roster list. This gives designers
65	// a complete network view of all player relationships at a glance.
66	export function PlayerRelationshipGraph({ players, selectedId, onSelect }: Props) {
67	  const svgRef = useRef<SVGSVGElement>(null);
68	  const containerRef = useRef<HTMLDivElement>(null);
69	
70	  // Store per-node circle/ring elements so selection can update them without
71	  // rebuilding the simulation.
72	  const nodeElsRef = useRef<Map<number, { circle: SVGCircleElement; ring: SVGCircleElement }>>(new Map());
73	  // Store a stable ref to selectedId so the selection-update effect can read
74	  // the latest value without triggering the simulation rebuild.
75	  const selectedIdRef = useRef<number | null>(selectedId);
76	  selectedIdRef.current = selectedId;
77	
78	  const { nodes, links } = useMemo(() => {
79	    const nodes: GraphNode[] = players.map((p) => ({
80	      id: p.id,
81	      name: p.name,
82	      playerType: (p.playerType as string) ?? "Character",
83	    }));
84	
85	    const idSet = new Set(players.map((p) => p.id));
86	    const links: GraphLink[] = [];
87	    const seen = new Set<string>();
88	
89	    for (const p of players) {
90	      const rels = castRelationships(p.relationships);
91	      for (const rel of rels) {
92	        if (!idSet.has(rel.targetPlayerId)) continue;
93	        const key = [Math.min(p.id, rel.targetPlayerId), Math.max(p.id, rel.targetPlayerId), rel.relationshipType].join(":");
94	        if (seen.has(key)) continue;
95	        seen.add(key);
96	        // Use numeric IDs — d3 resolves these to node objects during simulation init.
97	        links.push({ source: p.id, target: rel.targetPlayerId, label: rel.relationshipType });
98	      }
99	    }
100	
101	    return { nodes, links };
102	  }, [players]);
103	
104	  // ── Main simulation effect — only rebuilds when cast topology changes ──────
105	  // selectedId is intentionally excluded from deps; selection highlights are
106	  // updated in a separate effect below without restarting the simulation.
107	  useEffect(() => {
108	    const svg = svgRef.current;
109	    const container = containerRef.current;
110	    if (!svg || !container) return;
111	
112	    const W = container.clientWidth || 400;
113	    const H = container.clientHeight || 400;
114	
115	    svg.setAttribute("width", String(W));
116	    svg.setAttribute("height", String(H));
117	    svg.innerHTML = "";
118	    nodeElsRef.current.clear();
