122	    const ns = "http://www.w3.org/2000/svg";
123	
124	    const defs = document.createElementNS(ns, "defs");
125	    const marker = document.createElementNS(ns, "marker");
126	    marker.setAttribute("id", "arrow");
127	    marker.setAttribute("viewBox", "0 -5 10 10");
128	    marker.setAttribute("refX", "22");
129	    marker.setAttribute("refY", "0");
130	    marker.setAttribute("markerWidth", "6");
131	    marker.setAttribute("markerHeight", "6");
132	    marker.setAttribute("orient", "auto");
133	    const arrowPath = document.createElementNS(ns, "path");
134	    arrowPath.setAttribute("d", "M0,-5L10,0L0,5");
135	    arrowPath.setAttribute("fill", "#475569");
136	    marker.appendChild(arrowPath);
137	    defs.appendChild(marker);
138	    svg.appendChild(defs);
139	
140	    const g = document.createElementNS(ns, "g");
141	    svg.appendChild(g);
142	
143	    const linkEls: SVGLineElement[] = [];
144	    const labelEls: SVGTextElement[] = [];
145	
146	    for (const link of links) {
147	      const line = document.createElementNS(ns, "line") as SVGLineElement;
148	      line.setAttribute("stroke", relColor(link.label));
149	      line.setAttribute("stroke-width", "1.5");
150	      line.setAttribute("stroke-opacity", "0.6");
151	      line.setAttribute("marker-end", "url(#arrow)");
152	      g.appendChild(line);
153	      linkEls.push(line);
154	
155	      const text = document.createElementNS(ns, "text") as SVGTextElement;
156	      text.setAttribute("font-size", "9");
157	      text.setAttribute("fill", relColor(link.label));
158	      text.setAttribute("fill-opacity", "0.8");
159	      text.setAttribute("text-anchor", "middle");
160	      text.setAttribute("dominant-baseline", "middle");
161	      text.textContent = link.label;
162	      g.appendChild(text);
163	      labelEls.push(text);
164	    }
165	
166	    const nodeEls: Array<{ id: number; circle: SVGCircleElement; text: SVGTextElement; ring: SVGCircleElement; nameLabel: SVGTextElement }> = [];
167	
168	    for (const node of nodes) {
169	      const color = nodeColor(node.playerType);
170	      const isSelected = node.id === selectedIdRef.current;
171	
172	      const ring = document.createElementNS(ns, "circle") as SVGCircleElement;
173	      ring.setAttribute("r", "20");
174	      ring.setAttribute("fill", "none");
175	      ring.setAttribute("stroke", color);
176	      ring.setAttribute("stroke-width", isSelected ? "2.5" : "0");
177	      ring.setAttribute("stroke-opacity", "0.8");
178	      g.appendChild(ring);
179	
180	      const circle = document.createElementNS(ns, "circle") as SVGCircleElement;
181	      circle.setAttribute("r", "16");
182	      circle.setAttribute("fill", `${color}${isSelected ? "44" : "22"}`);
183	      circle.setAttribute("stroke", color);
184	      circle.setAttribute("stroke-width", isSelected ? "2.5" : "1.5");
185	      circle.setAttribute("cursor", "pointer");
186	      g.appendChild(circle);
187	
188	      const text = document.createElementNS(ns, "text") as SVGTextElement;
189	      text.setAttribute("font-size", "11");
190	      text.setAttribute("font-weight", "600");
191	      text.setAttribute("fill", color);
192	      text.setAttribute("text-anchor", "middle");
193	      text.setAttribute("dominant-baseline", "central");
194	      text.setAttribute("pointer-events", "none");
195	      text.textContent = initials(node.name);
196	      g.appendChild(text);
197	
198	      const nameLabel = document.createElementNS(ns, "text") as SVGTextElement;
199	      nameLabel.setAttribute("font-size", "9");
200	      nameLabel.setAttribute("fill", "#cbd5e1");
201	      nameLabel.setAttribute("text-anchor", "middle");
202	      nameLabel.setAttribute("dominant-baseline", "middle");
203	      nameLabel.setAttribute("pointer-events", "none");
