206	
207	      circle.addEventListener("click", () => onSelect(node.id));
208	      circle.addEventListener("mouseenter", () => {
209	        circle.setAttribute("fill", `${color}44`);
210	      });
211	      circle.addEventListener("mouseleave", () => {
