237	
238	    const R = 16;
239	
240	    sim.on("tick", () => {
241	      simNodes.forEach((n) => {
242	        n.x = Math.max(R + 4, Math.min(W - R - 4, n.x ?? W / 2));
243	        n.y = Math.max(R + 18, Math.min(H - R - 4, n.y ?? H / 2));
244	      });
245	
246	      simLinks.forEach((l, i) => {
247	        const src = l.source as GraphNode;
248	        const tgt = l.target as GraphNode;
249	        const line = linkEls[i]!;
250	        const lbl = labelEls[i]!;
251	        line.setAttribute("x1", String(src.x));
252	        line.setAttribute("y1", String(src.y));
253	        line.setAttribute("x2", String(tgt.x));
254	        line.setAttribute("y2", String(tgt.y));
255	        lbl.setAttribute("x", String(((src.x ?? 0) + (tgt.x ?? 0)) / 2));
256	        lbl.setAttribute("y", String(((src.y ?? 0) + (tgt.y ?? 0)) / 2 - 8));
257	      });
258	
259	      simNodes.forEach((n, i) => {
260	        const { circle, text, ring, nameLabel } = nodeEls[i]!;
261	        circle.setAttribute("cx", String(n.x));
262	        circle.setAttribute("cy", String(n.y));
263	        text.setAttribute("x", String(n.x));
264	        text.setAttribute("y", String(n.y));
265	        ring.setAttribute("cx", String(n.x));
266	        ring.setAttribute("cy", String(n.y));
267	        nameLabel.setAttribute("x", String(n.x));
268	        nameLabel.setAttribute("y", String((n.y ?? 0) + 28));
269	      });
270	    });
271	
272	    return () => { sim.stop(); };
273	  // eslint-disable-next-line react-hooks/exhaustive-deps
274	  }, [nodes, links]); // intentionally excludes selectedId — see selection effect below
275	
276	  // ── Selection highlight effect — updates ring/fill without resetting sim ──
277	  useEffect(() => {
278	    nodeElsRef.current.forEach(({ circle, ring }, nodeId) => {
279	      const colorKey = nodes.find((n) => n.id === nodeId)?.playerType ?? "Character";
280	      const color = nodeColor(colorKey);
281	      const isSelected = nodeId === selectedId;
282	      ring.setAttribute("stroke-width", isSelected ? "2.5" : "0");
283	      circle.setAttribute("fill", `${color}${isSelected ? "44" : "22"}`);
284	      circle.setAttribute("stroke-width", isSelected ? "2.5" : "1.5");
285	    });
286	  }, [selectedId, nodes]);
287	
288	  const hasRelationships = links.length > 0;
289	
290	  return (
291	    <div ref={containerRef} className="relative w-full h-full bg-card/20">
292	      <svg ref={svgRef} className="w-full h-full" />
293	      {nodes.length === 0 && (
294	        <div className="absolute inset-0 flex items-center justify-center">
295	          <p className="text-xs text-muted-foreground">No characters yet</p>
296	        </div>
297	      )}
298	      {nodes.length > 0 && !hasRelationships && (
299	        <div className="absolute bottom-3 left-0 right-0 flex justify-center pointer-events-none">
300	          <p className="text-[10px] text-muted-foreground bg-background/80 px-3 py-1 rounded-full border border-border">
301	            Open a character sheet and add relationships to see connections
302	          </p>
303	        </div>
304	      )}
305	    </div>
306	  );
307	}
