76	function detectTerms(text: string): Map<string, number> {
77	  const m = new Map<string, number>();
78	  const raw = text.match(/\b[A-Z][a-z]+(?:\s+[A-Z][a-z]+){0,2}\b/g);
79	  if (!raw) return m;
80	  const stop = new Set(["The","And","For","But","Not","Are","With","From","This","That","Have","They","Will","Would","Should","Could","Each","Every","Some","Many","Most","More","Less","Very","Just","Only","Also","Even","Such","Than","Then","When","Where","What","Which","While","After","Before","During","Above","Below","Under","Over","Into","Upon","Within","Without","Through","Across","Around","Behind","Beside","Beyond","Inside","Outside","Toward","Towards"]);
81	  raw.forEach(t => { if (t.length <= 3 || stop.has(t)) return; m.set(t, (m.get(t) || 0) + 1); });
82	  return m;
83	}
